/* ===== 💡 GABAY (hint/tutorial text) — on/off kada menu, para sa admin/super admin ===== */
(function () {
  const $ = id => document.getElementById(id); let OFF = {}, CUR = '', loaded = false;
  const D = () => { try { return window.db || (window.firebase && firebase.firestore()); } catch (e) { return null; } };
  const isA = () => { try { const u = (window.getCurrentUser && getCurrentUser()) || window.currentUser || {}; return /admin|super/i.test(String(u.role || '')) || !!window.IS_SUPER_ADMIN; } catch (e) { return false; } };
  const css = () => { if ($('kg-css')) return; const s = document.createElement('style'); s.id = 'kg-css'; s.textContent = '.kg-off .hint,.kg-off .guide,.kg-off .tip,.kg-off .help-text,.kg-off [data-guide],.kg-off .px-hint{display:none!important}'; document.head.appendChild(s); };
  const apply = () => { css(); document.body.classList.toggle('kg-off', !!OFF[CUR]); window.KGUIDE_OFF = OFF; window.kGuideOn = m => !OFF[m]; try { if (typeof PX !== 'undefined' && PX) PX.guideOff = !!OFF.pos; } catch (e) {} };
  async function load() { const d = D(); if (!d) return; try { const r = await d.collection('system_settings').doc('guides').get(); OFF = (r.exists && r.data().off) || {}; loaded = true; apply(); } catch (e) {} }
  function mods() { return [...document.querySelectorAll('.menu-item[data-module]')].map(a => ({ k: a.dataset.module, n: (a.textContent || '').trim() })).filter(x => x.k && x.n && x.k !== 'undefined'); }
  async function panel() { await load(); const L = mods(); const ov = document.createElement('div'); ov.style.cssText = 'position:fixed;inset:0;background:#0007;z-index:99999;display:flex;align-items:center;justify-content:center;padding:12px';
    ov.innerHTML = '<div style="background:#fff;color:#111;border-radius:12px;max-width:460px;width:100%;max-height:85vh;overflow:auto;padding:16px"><h3 style="margin:0 0 6px">💡 Mga Gabay</h3><div style="font-size:13px;color:#555;margin-bottom:10px">I-OFF ang gabay/tutorial text ng menu na marunong na ang lahat. Hindi nito binubura ang mga button o field — mga paliwanag lang.</div>' + L.map(x => '<label style="display:flex;justify-content:space-between;align-items:center;padding:7px 4px;border-bottom:1px solid #eee"><span>' + x.n.replace(/</g, '&lt;') + '</span><span><input type="checkbox" data-k="' + x.k + '" ' + (OFF[x.k] ? '' : 'checked') + '> ON</span></label>').join('') + '<div style="text-align:right;margin-top:12px"><button id="kg-x" style="padding:8px 14px">Isara</button></div></div>';
    document.body.appendChild(ov); $('kg-x').onclick = () => ov.remove();
    ov.querySelectorAll('input[data-k]').forEach(c => c.onchange = async () => { const k = c.dataset.k; if (c.checked) delete OFF[k]; else OFF[k] = true; apply(); try { await D().collection('system_settings').doc('guides').set({ off: OFF, by: ((window.getCurrentUser && getCurrentUser()) || {}).email || '', at: new Date().toISOString() }); } catch (e) { alert('Hindi na-save: ' + e.message); } }); }
  window.kGuidePanel = panel;
  function mount() { const pos = document.querySelector('.menu-item[data-module="pos"]'); if (!pos || $('kg-menu') || !isA()) return; const m = document.createElement('a'); m.id = 'kg-menu'; m.href = 'javascript:void(0)'; m.className = pos.className; m.innerHTML = '<i>💡</i> Mga Gabay (on/off)'; m.onclick = panel; pos.parentNode.appendChild(m); }
  function hook() { const o = window.switchAdminView; if (typeof o === 'function' && !o._kg) { const w = function (v) { CUR = v; setTimeout(apply, 30); return o.apply(this, arguments); }; w._kg = 1; window.switchAdminView = w; } }
  const boot = () => { load(); hook(); setInterval(() => { try { mount(); hook(); } catch (e) {} }, 2000); };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => setTimeout(boot, 800)); else setTimeout(boot, 800);
})();
